import React, { useCallback, useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";

import BookingList from "../components/BookingList";
import BookingForm from "../components/BookingForm";   // ✅ ADD
import InchargeModal from "../components/InchargeModal";
import Navbar from "../components/Navbar";
import RejectModal from "../components/RejectModal";
import Sidebar from "../components/Sidebar";
import { useAppContext } from "../context/AppContext";
import api from "../services/api";

const initialStats = {
  total: 0,
  pending: 0,
  approved: 0,
  rejected: 0,
};

const ClientDashboard = ({ view = "overview" }) => {   // ✅ IMPORTANT
  const navigate = useNavigate();
  const { incharges, fetchInitialData } = useAppContext();

  const [bookings, setBookings] = useState([]);
  const [stats, setStats] = useState(initialStats);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [initialLoadDone, setInitialLoadDone] = useState(false);

  const [showIncharges, setShowIncharges] = useState(false);
  const [cancelBookingId, setCancelBookingId] = useState(null);

  // ✅ FIXED MENU ROUTES
  const menuItems = useMemo(
    () => [
      { key: "overview", label: "Overview", to: "/", icon: "🏠" },
      { key: "new-booking", label: "New Booking", to: "/new-booking", icon: "➕" },
      { key: "my-bookings", label: "My Bookings", to: "/my-bookings", icon: "📋" },
      { key: "incharges", label: "Incharges", icon: "👨‍💼" },
    ],
    []
  );

  // LOGOUT
  const handleLogout = useCallback(() => {
    localStorage.clear();
    navigate("/login");
  }, [navigate]);

  // FETCH DASHBOARD
  const fetchDashboard = useCallback(async (force = false) => {
    try {
      if (!initialLoadDone) setLoading(true);

      const cachedStats = localStorage.getItem("dashboard");
      const cachedBookings = localStorage.getItem("bookings");

      if (cachedStats) setStats(JSON.parse(cachedStats));
      if (cachedBookings) setBookings(JSON.parse(cachedBookings));

      const [dashboardRes, bookingsRes] = await Promise.all([
        api.get("/client/dashboard", { cache: !force }),
        api.get("/client/bookings", { cache: !force }),
      ]);

      setStats(dashboardRes.data || initialStats);
      setBookings(bookingsRes.data || []);

      localStorage.setItem("dashboard", JSON.stringify(dashboardRes.data));
      localStorage.setItem("bookings", JSON.stringify(bookingsRes.data));

      setTimeout(() => {
        fetchInitialData?.({ force });
      }, 0);

      setError("");
    } catch (err) {
      if (err.response?.status === 401) {
        localStorage.clear();
        navigate("/login");
        return;
      }

      setError(
        err.response?.data?.detail ||
        err.message ||
        "Server not reachable"
      );
    } finally {
      setLoading(false);
      setInitialLoadDone(true);
    }
  }, [fetchInitialData, initialLoadDone, navigate]);

  useEffect(() => {
    fetchDashboard();
  }, [fetchDashboard]);

  const handleRefresh = useCallback(async () => {
    setRefreshing(true);
    api.clearCache(["/client/dashboard", "/client/bookings"]);
    await fetchDashboard(true);
    setRefreshing(false);
  }, [fetchDashboard]);

  const handleCancel = useCallback((id) => {
    setCancelBookingId(id);
  }, []);

  const handleCancelSubmit = useCallback(async (reason) => {
    try {
      await api.post(`/client/bookings/${cancelBookingId}/cancel`, { reason });

      setCancelBookingId(null);
      localStorage.removeItem("dashboard");
      localStorage.removeItem("bookings");

      fetchDashboard(true);
    } catch {
      alert("Cancel failed");
    }
  }, [cancelBookingId, fetchDashboard]);

  const recentBookings = useMemo(() => bookings.slice(0, 3), [bookings]);

  // ✅ MAIN VIEW SWITCH (REAL FIX)
  const renderContent = () => {
    if (loading && !initialLoadDone) return <p>Loading...</p>;

    switch (view) {
      case "new-booking":
        return <BookingForm />;

      case "my-bookings":
        return (
          <BookingList
            title="My Bookings"
            bookings={bookings}
            onCancel={handleCancel}
          />
        );

      default:
        return (
          <>
            <section className="stats-grid">
              <div className="card total">
                <p>Total</p>
                <h2>{stats.total}</h2>
              </div>
              <div className="card pending">
                <p>Pending</p>
                <h2>{stats.pending}</h2>
              </div>
              <div className="card approved">
                <p>Approved</p>
                <h2>{stats.approved}</h2>
              </div>
              <div className="card rejected">
                <p>Rejected</p>
                <h2>{stats.rejected}</h2>
              </div>
            </section>

            <BookingList
              title="Recent Bookings"
              bookings={recentBookings}
              onCancel={handleCancel}
            />
          </>
        );
    }
  };

  return (
    <div className="dashboard-shell">
      <Sidebar
        role="Client"
        items={menuItems}
        onLogout={handleLogout}
        onSelect={(key) => key === "incharges" && setShowIncharges(true)}
      />

      <main className="dashboard-main">
        <Navbar
          title="Client Dashboard"
          onRefresh={handleRefresh}
          refreshing={refreshing}
        />

        {error && (
          <div className="error-box">
            {error}
            <button onClick={handleRefresh}>Retry</button>
          </div>
        )}

        {/* ✅ FINAL OUTPUT */}
        {renderContent()}
      </main>

      <InchargeModal
        open={showIncharges}
        groups={incharges}
        onClose={() => setShowIncharges(false)}
      />

      <RejectModal
        open={Boolean(cancelBookingId)}
        onClose={() => setCancelBookingId(null)}
        onSubmit={handleCancelSubmit}
      />
    </div>
  );
};

export default ClientDashboard;
